<section class="account-section" id="profile"><h2>Your details</h2><?php ui_form_start('/api/account/profile','form-card','/account#profile');ui_input('name','Full name','text',true,$user['name']);?><p class="catalog-note">Email: <?=ui_e($user['email'])?>. Changes to your email require verification.</p><button class="button primary">Save profile</button></form></section>
<section class="account-section" id="addresses"><div class="section-heading"><h2>Saved addresses</h2><span><?=count($account['addresses'])?> / 20</span></div><?php foreach($account['addresses'] as $address):?><details class="admin-record"><summary><strong><?=ui_e($address['label'])?></strong><span><?=ui_e($address['city'])?></span></summary><?php ui_form_start('/api/account/addresses','', '/account#addresses');?><input type="hidden" name="id" value="<?=(int)$address['id']?>"><?php ui_input('label','Label','text',true,$address['label']);ui_input('address','Street address','text',true,$address['address']);ui_input('city','Town / city','text',true,$address['city']);ui_input('postal_code','Postal code','text',true,$address['postal_code']);?><button class="button primary">Save address</button></form><?php ui_form_start('/api/account/addresses/remove','compact-form','/account#addresses');?><input type="hidden" name="id" value="<?=(int)$address['id']?>"><button class="button secondary">Remove address</button></form></details><?php endforeach;?><details class="admin-record"><summary><strong>Add an address</strong><?=ui_icon('plus')?></summary><?php ui_form_start('/api/account/addresses','','/account#addresses');ui_input('label','Address label');ui_input('address','Street address');ui_input('city','Town / city');ui_input('postal_code','Postal code');?><button class="button primary">Save new address</button></form></details></section>
